fn read_child_output(&mut self) -> io::Result<(Vec<u8>, Vec<u8>)> {
    self.stdout.rewind()?;
    let mut stdout = Vec::new();
    self.stdout.read_to_end(&mut stdout)?;
    self.stderr.rewind()?;
    let mut stderr = Vec::new();
    self.stderr.read_to_end(&mut stderr)?;
    Ok((stdout, stderr))
}

